"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[1642],{3345(e){e.exports=JSON.parse('{"title":"\ud504\ub808\uc784\uc6cc\ud06c\ub97c \ubc30\uc6b8 \uc2dc\uac04\uc740 \uc5c6\ub2e4","date":"2025-07-09","coverUrl":"/kudzu-based-bench/assets/notion/6f2bda4c67ffdf16.png","html":"<h1 data-notion-block-id=\\"224e548d-8a8e-803d-8f7a-fba0b83856e8\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"228e548d-8a8e-807f-8b07-f2cb577990f5\\" id=\\"228e548d-8a8e-807f-8b07-f2cb577990f5\\">\ud504\ub808\uc784\uc6cc\ud06c\ub97c \ubc30\uc6b8 \uc2dc\uac04\uc740 \uc5c6\ub2e4.</h2><a href=\\"https://brainbaking.com/post/2025/06/no-time-to-learn-web-framework-x/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://brainbaking.com/post/2025/06/no-time-to-learn-web-framework-x/</a><p data-notion-block-id=\\"224e548d-8a8e-80fc-a708-f5749d4ee72a\\">\ud504\ub808\uc784\uc6cc\ud06c\ub97c \ubc30\uc6b0\uc9c0 \ub9d0\uace0 \uc6f9 \ud45c\uc900\uc774\ub098 HTML, CSS, JS\uac19\uc740 \uae30\ubc18 \uae30\uc220\uc744 \ubc30\uc6b0\ub77c\ub294 \uac04\ub2e8\ud55c \uc774\uc57c\uae30\uc774\uc9c0\ub9cc, \uc5b4\ub5bb\uac8c \ubcf4\uba74 2025\ub144\uc5d0\ub3c4 \ubc14\ub00c\ub294 JS\ub098 Go\uc5b8\uc5b4\ub97c \ubcf4\uba74\uc11c \uae30\ubc18 \uae30\uc220 \ub610\ud55c \ubc14\ub00c\ubbc0\ub85c, \uac01\uc790\uac00 \uc0dd\uac01\ud558\ub294 \uadfc\uac04 \uae30\uc220\uc744 \ubc30\uc6b0\ub294 \uac83\uc774 \uc88b\ub2e4\ub294 \uac83\uc744 \uc8fc\uc7a5\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uae00\uc5d0\uc11c \uc124\uba85\ud558\ub4ef\uc774 \uc6f9 \ud45c\uc900\uc73c\ub85c \uc4f0\uc5ec\uc788\ub294 Web components\ubcf4\ub2e4 React\uc758 \uc0dd\ud0dc\uacc4\uac00 \ub354 \ud65c\ubc1c\ud558\uace0, \uac80\uc99d\ub418\uc5b4 \uc788\ub2e4\ub294 \uac83 \uac19\uc774\uc694. <a href=\\"https://mbrizic.com/blog/react-is-insane/\\">React\uac00 \ud544\uc694\uc5c6\ub2e4\ub294 \uc785\uc7a5</a>\uacfc React\uac00 \ud3b8\ud558\ub2e4\ub294 \uc785\uc7a5\uc774 \uacf5\uc874\ud558\ub294 \uac83\ucc98\ub7fc \uc5b8\uc81c\ub098 \uadfc\uac04 \uae30\uc220\uc774\ub77c\uace0 \uc0dd\uac01\ud558\ub294 \uac83\uc740 \uc0ac\ub78c\ub9c8\ub2e4 \ub2e4\ub974\uace0, \uc0c1\ud669\ub9c8\ub2e4 \ub2e4\ub974\ub2e4\ub294 \uac83\uc744 \uc54c\uace0 \uacc4\uc168\uc73c\uba74 \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"228e548d-8a8e-801a-bcb8-e6cc4e2dbc0b\\" id=\\"228e548d-8a8e-801a-bcb8-e6cc4e2dbc0b\\">2025\ub144 Node.js Best practice</h2><a href=\\"https://kashw1n.com/blog/nodejs-2025/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kashw1n.com/blog/nodejs-2025/</a><p data-notion-block-id=\\"228e548d-8a8e-8003-98a5-ec00cad5c209\\"><code>node</code>\uc758 \ucd5c\uc2e0 \uc2dc\uc2a4\ud15c(ex. \ubaa8\ub4c8, \ucd5c\uc0c1\uc704 await, \ud14c\uc2a4\ud2b8 \ub7ec\ub108\u2026)\uc640 \uc5ec\ub7ec \uc608\uc2dc\ub294 \ucd5c\uc2e0 Node.js\uc5d0\uc11c\ub294 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\uba70, <code>Nuxt.js</code>\ub098 <code>Next.js</code> standalone\uc5d0\uc11c\ub294 \uc77c\ubd80 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc0dd\uac01\ud558\uba74\uc11c Node.js \ub124\uc774\ud2f0\ube0c\ub97c \uc0ac\uc6a9\ud560\uc9c0 \ub9d0\uc9c0\ub97c \uace0\ubbfc\ud574\uc57c\uaca0\uc2b5\ub2c8\ub2e4. deno\uc5d0 \uba3c\uc800 \uc788\ub358 <code>--allow-fs-read</code>\uac19\uc740 \uad8c\ud55c \ubaa8\ub378\uc740 \uc88b\uc544\ubcf4\uc774\ub124\uc694!</p><h2 data-notion-block-id=\\"228e548d-8a8e-809c-bf43-c078526c5ef3\\" id=\\"228e548d-8a8e-809c-bf43-c078526c5ef3\\">Storybook\uc758 \uc811\uadfc\uc131 \ud30c\uc774\ud504\ub77c\uc778</h2><a href=\\"https://storybook.js.org/blog/the-accessibility-pipeline-for-frontend-teams/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://storybook.js.org/blog/the-accessibility-pipeline-for-frontend-teams/</a><p data-notion-block-id=\\"228e548d-8a8e-801d-8eef-e0ab5ce5c9e9\\"><a href=\\"https://slack.engineering/automated-accessibility-testing-at-slack/\\">Slack\ud300\uc774 Playwright + Axe\ud638\ucd9c\uc744 \uc811\uadfc\uc131 \ud14c\uc2a4\ud2b8 \uc77c\ubd80\ub9cc \uc790\ub3d9\ud654</a> \ud558\ub4ef\uc774, \uc811\uadfc\uc131 \ud14c\uc2a4\ud2b8\ub294 \uc624\ub798 \uac78\ub9ac\uace0 \ubd88\ud3b8\ud558\uc9c0\ub9cc, \ud544\uc694\ud55c \ubd80\ubd84\uc785\ub2c8\ub2e4. Storybook\ud300\uc5d0\uc11c Storybook\uc73c\ub85c Component level\uc5d0\uc11c WCAG 2.1\uae30\ubc18 \uc811\uadfc\uc131 \ud14c\uc2a4\ud2b8\ub97c \ud558\uace0, Chromatic\uc73c\ub85c \uc2dc\uac01\uc801 \ud68c\uadc0 \ud14c\uc2a4\ud2b8\ub97c \ud558\ub294 \ud30c\uc774\ud504\ub77c\uc778\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"224e548d-8a8e-804a-becf-fa999580178f\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"228e548d-8a8e-80e7-9785-dfa110eaf44f\\" id=\\"228e548d-8a8e-80e7-9785-dfa110eaf44f\\">Remix\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158, \uc5b4\ub5a4 \uc774\uc810\uc744 \uac00\uc838\uc654\ub294\uac00</h2><a href=\\"https://shopify.engineering/remixing-admin\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shopify.engineering/remixing-admin</a><p data-notion-block-id=\\"228e548d-8a8e-800f-bc3c-eeeb2b1eca15\\">Shopify\uac00 Remix\ub97c \uc778\uc218\ud558\uba74\uc11c Shopify\uc5d0\uc11c\ub3c4 Remix\ub97c \uc801\uc6a9\ud588\uc2b5\ub2c8\ub2e4. Remix\uc5d0\ub294 <a href=\\"https://remix.run/blog/remix-data-flow\\">loader \ud328\ud134</a>, <a href=\\"https://remix.run/blog/fog-of-war#the-route-manifest\\">\uacbd\ub85c\ub9c8\ub2e4\uc758 \uc815\ubcf4</a>\ub97c \uac00\uc838\uc624\ub294 \uae30\ub2a5\uc744 \ud65c\uc6a9\ud558\uba74\uc11c \uc5b4\ub5a4 \uc774\uc810\uc774 \uc788\uc5c8\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Remix\uc758 \uc6f9 \ud45c\uc900\uc744 \uc9c0\ud0a4\ub824\ub294 \ub178\ub825\uc774\ub098 <a href=\\"https://remix.run/blog/wake-up-remix\\">Remix\ub97c framework agnostic\ud558\uac8c \ub9cc\ub4dc\ub824\ub294 \uc6c0\uc9c1\uc784</a>\uc740 \uc8fc\ubaa9\ud574\ubcfc\ub9cc \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"228e548d-8a8e-80aa-90aa-c18e7e7901e1\\" id=\\"228e548d-8a8e-80aa-90aa-c18e7e7901e1\\">CustomEvent\ub97c \uadf8\ub9cc \uc0ac\uc6a9\ud558\uc790</h2><a href=\\"https://justinfagnani.com/2025/06/25/stop-using-custom-event/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://justinfagnani.com/2025/06/25/stop-using-custom-event/</a><h2 data-notion-block-id=\\"228e548d-8a8e-80a9-a174-caa4f60f302b\\" id=\\"228e548d-8a8e-80a9-a174-caa4f60f302b\\">\ucd5c\uc2e0 CSS\ub85c Select \ucee4\uc2a4\ud140\ud558\uae30</h2><a href=\\"https://frontendmasters.com/blog/custom-select-that-comes-up-from-the-bottom-on-mobile/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/custom-select-that-comes-up-from-the-bottom-on-mobile/</a><h2 data-notion-block-id=\\"228e548d-8a8e-80a1-8373-f51903e8f5e6\\" id=\\"228e548d-8a8e-80a1-8373-f51903e8f5e6\\">Virtualizing. \uc5b4\ub5a4 \uac83\uc774\uace0 \uc5b4\ub5a4 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc788\uc744\uae4c</h2><a href=\\"https://d2.naver.com/helloworld/4706492\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://d2.naver.com/helloworld/4706492</a><p data-notion-block-id=\\"228e548d-8a8e-808d-b3fb-f1157cd438c8\\">\ub2e4\ub978 Windowing\uc758 \uac1c\ub150\uacfc \uc5b4\ub5bb\uac8c \ud65c\uc6a9\ud588\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4. <a href=\\"https://ridicorp.com/story/ridi-markdown-improvements/\\">RIDI \ud300\uc758 Virtualizing \uc18c\uac1c \ubc0f \uc131\ub2a5 \ucd5c\uc801\ud654 \uae00</a> \ucc98\ub7fc, \ub2e4\ub978 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc18c\uac1c\ud588\uace0, \uadf8 \uc774\ud6c4 \uc5b4\ub5a4 \ubb38\uc81c\uac00 \uc0dd\uacbc\ub294\uc9c0\uae4c\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"225e548d-8a8e-806a-8fe3-c55fb02612c6\\" id=\\"225e548d-8a8e-806a-8fe3-c55fb02612c6\\">\uc77c\ubc18 \ud568\uc218\uc640 \ud654\uc0b4\ud45c \ud568\uc218\uc758 \ucc28\uc774</h2><a href=\\"https://jrsinclair.com/articles/2025/whats-the-difference-between-named-functions-and-arrow-functions/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jrsinclair.com/articles/2025/whats-the-difference-between-named-functions-and-arrow-functions/</a><h1 data-notion-block-id=\\"224e548d-8a8e-805e-825b-c6d492758f60\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://turso.tech/blog/turso-the-next-evolution-of-sqlite\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://turso.tech/blog/turso-the-next-evolution-of-sqlite</a><p data-notion-block-id=\\"228e548d-8a8e-803e-83fe-d5f863065289\\">Turso\ud300\uc774 SQLite\uc758 Rust \uc7ac\uc791\uc131 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ubc1c\ud45c\ud588\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://x.com/rauchg/status/1938668763525849298\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://x.com/rauchg/status/1938668763525849298</a><p data-notion-block-id=\\"228e548d-8a8e-80f0-accf-c7ded65c7d10\\">Next.js\uc5d0\uc11c\uc758 turbopack \uc0ac\uc6a9 \ud14c\uc2a4\ud2b8\uac00 \ubaa8\ub450 \ud1b5\uacfc\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. \uace7 turbopack \uc0ac\uc6a9\uc744 \uae30\ubcf8\uc73c\ub85c \ud560\uc9c0\ub3c4 \ubaa8\ub974\uaca0\ub124\uc694!</p><a href=\\"https://astro.build/blog/live-content-collections-deep-dive/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://astro.build/blog/live-content-collections-deep-dive/</a><p data-notion-block-id=\\"225e548d-8a8e-80a8-8ad8-e5498d255450\\">Astro 5.10\ubc84\uc804\uc5d0 Live Content Collection\uc774 \uc0dd\uacbc\uc2b5\ub2c8\ub2e4. \uc774\ub97c \uc5b4\ub5bb\uac8c \uc4f0\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://2ality.com/2025/06/ecmascript-2025.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://2ality.com/2025/06/ecmascript-2025.html</a><p data-notion-block-id=\\"228e548d-8a8e-80c1-b63b-d9bce8ac51b5\\">ECMAScript 2025\ubc84\uc804\uc5d0\uc11c \uc5b4\ub5a4 \uc0c8\ub85c\uc6b4 \uac83\uc774 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/mrousavy/nitro\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/mrousavy/nitro</a><p data-notion-block-id=\\"225e548d-8a8e-804f-a417-e13db0bab4ab\\">React Native\uc5d0\uc11c \ud06c\ub85c\uc2a4 \ud50c\ub7ab\ud3fc \ubaa8\ub4c8\uc744 \ube60\ub974\uac8c \ub9cc\ub4e4 \uc218 \uc788\ub294 Nitro Modules\uc785\ub2c8\ub2e4. \uc608\uc2dc \ubaa8\ub4c8\uc774\ub098 <a href=\\"https://github.com/TheWidlarzGroup/react-native-video/releases/tag/v7.0.0-alpha.0\\">\uc7ac\uc791\uc131\ub41c \ub77c\uc774\ube0c\ub7ec\ub9ac</a>\ub3c4 \uc788\uc73c\ub2c8 \ud06c\ub85c\uc2a4 \ud50c\ub7ab\ud3fc RN \ubaa8\ub4c8\uc744 \ube60\ub974\uac8c \ub9cc\ub4e4 \uc218 \uc788\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"225e548d-8a8e-809c-9ed1-c90c85ec0841\\" id=\\"225e548d-8a8e-809c-9ed1-c90c85ec0841\\">\ubc88\uc678: \ud06c\ub864\ub9c1\ud560\uac70\uba74 \ub3c8\uc744 \ub0b4\uc138\uc694.</h2><a href=\\"https://blog.cloudflare.com/introducing-pay-per-crawl/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/introducing-pay-per-crawl/</a><p data-notion-block-id=\\"228e548d-8a8e-8039-b65a-d6d69af4cad1\\">Cloudflare\uc5d0\uc11c \uc790\uc2e0\uc758 \uc6f9\uc0ac\uc774\ud2b8\ub97c \ud06c\ub864\ub9c1\ud558\ub824\ub294 \ubd07\uc5d0\uac8c \ube44\uc6a9\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub3c4\ub85d \ud560 \uc218 \uc788\ub294 \uc11c\ube44\uc2a4\ub97c \ucd9c\uc2dc\ud588\uc2b5\ub2c8\ub2e4. \ubd07\uc774 \uc774\ub97c \ud68c\ud53c\ud560 \uc218\ub3c4 \uc788\uaca0\uc9c0\ub9cc, \ud765\ubbf8\ub86d\ub124\uc694.</p><h2 data-notion-block-id=\\"228e548d-8a8e-8075-bd45-e10b231a87bc\\" id=\\"228e548d-8a8e-8075-bd45-e10b231a87bc\\">\ubc88\uc678: \uc0c8\ub85c\uc6b4 PNG \uc0ac\uc591\uc774 \uacf5\uac1c\ub418\uc5c8\uc2b5\ub2c8\ub2e4!</h2><a href=\\"https://www.programmax.net/articles/png-is-back/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.programmax.net/articles/png-is-back/</a><p data-notion-block-id=\\"22ae548d-8a8e-80b5-8957-c7d48f39ab92\\">20\ub144\ub9cc\uc5d0 PNG\uc758 \uacf5\uc2dd \uc0ac\uc591\uc774 \uc5c5\ub370\uc774\ud2b8\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. HDR\uae30\ub2a5\uc774\ub098 \uc560\ub2c8\uba54\uc774\uc158 \uae30\ub2a5 \uacf5\uc2dd\ud654\uac00 \ub208\uc5d0 \ub744\ub124\uc694.</p>"}')}}]);